-- Retour arrière : recrée les règles d'accès telles qu'au 26/11/2026 avant le cloisonnement.
begin;
drop policy if exists "La direction consulte le journal d'activité" on public.activity_events;
drop policy if exists "Les agents gèrent les exemplaires" on public.book_copies;
drop policy if exists "Les exemplaires sont publics en lecture" on public.book_copies;
drop policy if exists "La direction supprime des livres" on public.books;
drop policy if exists "Les agents ajoutent des livres" on public.books;
drop policy if exists "La direction ajoute des livres" on public.books;
drop policy if exists "Le catalogue est public en lecture" on public.books;
drop policy if exists "La direction modifie les livres" on public.books;
drop policy if exists "Les agents modifient les livres" on public.books;
drop policy if exists "Un super-admin modifie les livres" on public.books;
drop policy if exists "Les agents voient les demandes de dépôt" on public.depot_requests;
drop policy if exists "Les agents voient les dépôts" on public.depots;
drop policy if exists "Les agents voient les ouvertures" on public.digital_resource_opens;
drop policy if exists "Un usager voit ses dettes" on public.document_debts;
drop policy if exists "Un usager voit ses dons de livres" on public.donations;
drop policy if exists "Agent ou super-admin voit les dons" on public.donations;
drop policy if exists "Les agents voient les inscrits sans compte" on public.event_rsvp_guests;
drop policy if exists "Un usager se désinscrit lui-même" on public.event_rsvps;
drop policy if exists "Un usager s'inscrit lui-même" on public.event_rsvps;
drop policy if exists "Les inscriptions sont publiques en lecture" on public.event_rsvps;
drop policy if exists "La direction supprime des événements" on public.events;
drop policy if exists "La direction ajoute des événements" on public.events;
drop policy if exists "Les événements sont publics en lecture" on public.events;
drop policy if exists "La direction modifie les événements" on public.events;
drop policy if exists "Un usager voit ses propres emprunts hors condition" on public.free_book_loans;
drop policy if exists "Un agent voit tous les emprunts hors condition" on public.free_book_loans;
drop policy if exists "Un agent met à jour les emprunts hors condition" on public.free_book_loans;
drop policy if exists "Un usager voit ses files d'attente" on public.holds;
drop policy if exists "Les agents gèrent les scans de récolement" on public.inventory_scans;
drop policy if exists "Les agents gèrent les prêts" on public.loans;
drop policy if exists "Un usager voit ses propres prêts" on public.loans;
drop policy if exists "Un super-admin voit tous les profils" on public.profiles;
drop policy if exists "Un agent voit tous les profils" on public.profiles;
drop policy if exists "Un usager voit son propre profil" on public.profiles;
drop policy if exists "Un usager modifie son propre profil" on public.profiles;
drop policy if exists "Un super-admin modifie tous les profils" on public.profiles;
drop policy if exists "Un usager retire un livre de son panier ou de sa commande" on public.reservations;
drop policy if exists "Un usager crée ses propres réservations" on public.reservations;
drop policy if exists "Un agent voit toutes les réservations" on public.reservations;
drop policy if exists "Un usager voit ses propres réservations" on public.reservations;
drop policy if exists "Un agent met à jour toutes les réservations" on public.reservations;
drop policy if exists "Un usager met à jour ses propres réservations" on public.reservations;
drop policy if exists "Les agents voient et gèrent les transferts" on public.transfers;
drop policy if exists "Un usager voit le transfert qui le concerne" on public.transfers;
drop policy if exists "Un agent ajoute des entrées visiteurs" on public.visitor_entries;
drop policy if exists "Un agent voit les entrées visiteurs" on public.visitor_entries;
drop policy if exists "Un agent corrige une entrée visiteur" on public.visitor_entries;
create policy "La direction consulte le journal d'activité" on public.activity_events for select to public using (is_direction());
create policy "Les agents gèrent les exemplaires" on public.book_copies for all to public using ((is_agent() OR is_super_admin())) with check ((is_agent() OR is_super_admin()));
create policy "Les exemplaires sont publics en lecture" on public.book_copies for select to public using ((NOT (owner_commune_id = ANY (( SELECT hidden_commune_ids() AS hidden_commune_ids)::bigint[]))));
create policy "La direction supprime des livres" on public.books for delete to public using (is_direction());
create policy "Les agents ajoutent des livres" on public.books for insert to public with check (is_agent());
create policy "La direction ajoute des livres" on public.books for insert to public with check (is_direction());
create policy "Le catalogue est public en lecture" on public.books for select to public using (((commune_id IS NULL) OR (NOT (commune_id = ANY (( SELECT hidden_commune_ids() AS hidden_commune_ids)::bigint[])))));
create policy "La direction modifie les livres" on public.books for update to public using (is_direction());
create policy "Les agents modifient les livres" on public.books for update to public using (is_agent());
create policy "Un super-admin modifie les livres" on public.books for update to public using (is_super_admin());
create policy "Les agents voient les demandes de dépôt" on public.depot_requests for select to public using ((is_agent() OR is_super_admin()));
create policy "Les agents voient les dépôts" on public.depots for select to public using ((is_agent() OR is_super_admin()));
create policy "Les agents voient les ouvertures" on public.digital_resource_opens for select to public using (is_agent());
create policy "Un usager voit ses dettes" on public.document_debts for select to public using (((auth.uid() = user_id) OR is_agent() OR is_super_admin()));
create policy "Un usager voit ses dons de livres" on public.donations for select to public using ((donor_id = auth.uid()));
create policy "Agent ou super-admin voit les dons" on public.donations for select to public using ((is_agent() OR is_super_admin()));
create policy "Les agents voient les inscrits sans compte" on public.event_rsvp_guests for select to public using (is_agent());
create policy "Un usager se désinscrit lui-même" on public.event_rsvps for delete to public using ((auth.uid() = user_id));
create policy "Un usager s'inscrit lui-même" on public.event_rsvps for insert to public with check ((auth.uid() = user_id));
create policy "Les inscriptions sont publiques en lecture" on public.event_rsvps for select to public using (true);
create policy "La direction supprime des événements" on public.events for delete to public using (is_direction());
create policy "La direction ajoute des événements" on public.events for insert to public with check (is_direction());
create policy "Les événements sont publics en lecture" on public.events for select to public using (true);
create policy "La direction modifie les événements" on public.events for update to public using (is_direction());
create policy "Un usager voit ses propres emprunts hors condition" on public.free_book_loans for select to public using ((auth.uid() = user_id));
create policy "Un agent voit tous les emprunts hors condition" on public.free_book_loans for select to public using (is_agent());
create policy "Un agent met à jour les emprunts hors condition" on public.free_book_loans for update to public using (is_agent());
create policy "Un usager voit ses files d'attente" on public.holds for select to public using (((auth.uid() = user_id) OR is_agent() OR is_super_admin()));
create policy "Les agents gèrent les scans de récolement" on public.inventory_scans for all to public using ((is_agent() OR is_super_admin())) with check ((is_agent() OR is_super_admin()));
create policy "Les agents gèrent les prêts" on public.loans for all to public using ((is_agent() OR is_super_admin())) with check ((is_agent() OR is_super_admin()));
create policy "Un usager voit ses propres prêts" on public.loans for select to public using (((auth.uid() = user_id) OR is_agent() OR is_super_admin()));
create policy "Un super-admin voit tous les profils" on public.profiles for select to public using (is_super_admin());
create policy "Un agent voit tous les profils" on public.profiles for select to public using (is_agent());
create policy "Un usager voit son propre profil" on public.profiles for select to public using ((auth.uid() = id));
create policy "Un usager modifie son propre profil" on public.profiles for update to public using ((auth.uid() = id));
create policy "Un super-admin modifie tous les profils" on public.profiles for update to public using (is_super_admin());
create policy "Un usager retire un livre de son panier ou de sa commande" on public.reservations for delete to public using (((auth.uid() = user_id) AND ((status = 'panier'::text) OR ((status = 'preparation'::text) AND (COALESCE(ordered_at, created_at) > (now() - '00:30:00'::interval))))));
create policy "Un usager crée ses propres réservations" on public.reservations for insert to public with check ((auth.uid() = user_id));
create policy "Un agent voit toutes les réservations" on public.reservations for select to public using (is_agent());
create policy "Un usager voit ses propres réservations" on public.reservations for select to public using ((auth.uid() = user_id));
create policy "Un agent met à jour toutes les réservations" on public.reservations for update to public using (is_agent());
create policy "Un usager met à jour ses propres réservations" on public.reservations for update to public using ((auth.uid() = user_id));
create policy "Les agents voient et gèrent les transferts" on public.transfers for all to public using ((is_agent() OR is_super_admin())) with check ((is_agent() OR is_super_admin()));
create policy "Un usager voit le transfert qui le concerne" on public.transfers for select to public using (((reservation_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM reservations r
  WHERE ((r.id = transfers.reservation_id) AND (r.user_id = auth.uid()))))));
create policy "Un agent ajoute des entrées visiteurs" on public.visitor_entries for insert to public with check ((is_agent() OR is_super_admin()));
create policy "Un agent voit les entrées visiteurs" on public.visitor_entries for select to public using ((is_agent() OR is_super_admin()));
create policy "Un agent corrige une entrée visiteur" on public.visitor_entries for update to public using ((is_agent() OR is_super_admin())) with check ((is_agent() OR is_super_admin()));
commit;
